def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        base = 18.0 if hp > 3 else 40.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    cindy_prev = None
    urgent_opp = 0
    rich_opp = 0
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if agent_id == 'Cindy' and bid is not None:
            cindy_prev = float(bid)
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= 200:
            rich_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    non_cindy_prev = []
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None and agent_id != 'Cindy':
            non_cindy_prev.append(float(bid))
    highest_non_cindy = max(non_cindy_prev) if non_cindy_prev else 0.0

    critical = hp <= 2 or no_water_days >= 1
    very_safe = hp >= 8 and no_water_days == 0
    low_supply = supply <= 17.0
    high_supply = supply >= 23.0

    bid = 0.0

    if critical:
        if cindy_prev is not None and cindy_prev >= 120.0 and budget > 150.0:
            bid = min(budget, 138.0)
        else:
            bid = min(budget, max(72.0, highest_non_cindy + 4.0, highest_prev * 0.9))
    else:
        if cindy_prev is not None and cindy_prev >= 120.0:
            if low_supply:
                bid = min(budget, max(58.0, highest_non_cindy + 3.0))
            elif high_supply and very_safe:
                bid = min(budget, 16.0)
            else:
                bid = min(budget, max(28.0, highest_non_cindy + 1.5))
        else:
            if low_supply:
                bid = min(budget, max(62.0, highest_prev + 2.0))
            elif high_supply:
                bid = min(budget, max(24.0, highest_non_cindy * 0.75 + 2.0))
            else:
                bid = min(budget, max(36.0, highest_non_cindy + 2.0))

    if urgent_opp >= 2 and not critical:
        bid = max(bid, min(budget, 52.0 if not low_supply else 66.0))

    if rich_opp == 0 and very_safe and high_supply:
        bid = min(bid, budget, 18.0)

    if day >= 8:
        if hp <= 4:
            bid = max(bid, min(budget, 78.0))
        elif budget < 80:
            bid = min(bid, budget, 30.0)

    if budget < 40:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(yesterday_bids)
    avg_prev = sum(yesterday_bids) / len(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev + 5.0)

    if supply < 18:
        return min(my_status['budget'], max(avg_prev + 2.0, DAILY_SALARY * 0.7))

    return min(my_status['budget'], max(avg_prev * 0.9, DAILY_SALARY * 0.4))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    max_prev_bid = 0
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            max_prev_bid = max(max_prev_bid, prev['bid'])

    base = DAILY_SALARY * 0.5
    total_required = WATER_REQ * (1 + len(alive_opponents))

    if supply < total_required:
        bid = max(base, DAILY_SALARY * 0.7)
        if max_prev_bid > DAILY_SALARY * 0.85:
            bid = max(bid, max_prev_bid + 1.0)
    else:
        bid = base

    if hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif hp <= 4 and no_water_days > 0:
        bid = max(bid, DAILY_SALARY * 0.7)

    bid = min(bid, budget, DAILY_SALARY)
    bid = max(bid, 0)
    return bid
